"use strict";
Object.defineProperty(exports, "__esModule", { value: true });
class default_1 {
    constructor() {
        this.eventMap = {};
    }
    on(type, fn) {
        (this.eventMap[type] = this.eventMap[type] || []).push(fn);
    }
    off(type, fn) {
        let eventList = this.eventMap[type];
        if (!fn)
            delete this.eventMap[type];
        else if (eventList)
            this.eventMap[type] = eventList.filter(item => item != fn);
    }
    emit(type, context, ...args) {
        let eventList = this.eventMap[type];
        if (eventList)
            eventList.forEach((fn) => {
                fn.apply(context, args);
            });
    }
}
exports.default = default_1;
